mapper.select:
select PROD_ADJUST_ID, DATA_STATUS dataStatus, PROD_REGIST_NO prodRegistNo, PROD_ID prodId, IS_SALES_AGENCY isSalesAgency, PROD_ADJ_REMARK prodAdjRemark, PROD_ADJ_REMARK2 prodAdjRemark2, ADJ_FIELD adjField, PRE_ADJUST preAdjust, AFTER_ADJUST afterAdjust, EFF_DATE effDate, FIELD_ADJ_REMARK fieldAdjRemark, FIELD_ADJ_REMARK2 fieldAdjRemark2, RPT_ISSUE_DATE rptIssueDate, UPDATE_TIME updateTime, UPDATE_USER updateUser from DIS_PROD_ADJUST
AND PROD_REGIST_NO in
#{item}
AND PROD_ID in
#{item}
AND ADJ_FIELD in
#{item}
AND IS_SALES_AGENCY=#{isSalesAgency}
AND DATA_STATUS=#{dataStatus}
AND RPT_ISSUE_DATE >= TO_DATE(#{rptIssueDateStart},'YYYY-MM-DD')
AND RPT_ISSUE_DATE <= TO_DATE(#{rptIssueDateEnd},'YYYY-MM-DD')

select PROD_REGIST_NO
from DIS_PROD_ADJUST
where PROD_REGIST_NO = #{prodRegistNo,jdbcType=VARCHAR}
